using Dip.Domain.Entities; using Dip.Domain.Enums; namespace Dip.Application.Features.Quality; public sealed record QualityGateResultDto(string Status,int CriticalCount,int WarningCount,decimal Score,IReadOnlyList<string> Reasons); public sealed class QualityGateEvaluator{public QualityGateResultDto Evaluate(IReadOnlyCollection<Metric> metrics,IReadOnlyCollection<QualityIssue> issues){var reasons=new List<string>();var critical=issues.Count(x=>x.Severity==Severity.Critical);var warnings=issues.Count(x=>x.Severity==Severity.Warning);foreach(var m in metrics){if(m.Name.Equals("average_fps",StringComparison.OrdinalIgnoreCase)&&m.DifferencePercent<=-10){critical++;reasons.Add($"FPS regressed by {Math.Abs(m.DifferencePercent.Value):0.##}%.");}else if(m.Name.Equals("average_fps",StringComparison.OrdinalIgnoreCase)&&m.DifferencePercent<=-5){warnings++;reasons.Add($"FPS regressed by {Math.Abs(m.DifferencePercent.Value):0.##}%.");}if(m.Name.Equals("memory_mb",StringComparison.OrdinalIgnoreCase)&&m.DifferencePercent>=20){critical++;reasons.Add($"Memory increased by {m.DifferencePercent.Value:0.##}%.");}}var status=critical>0?QualityGateStatus.Fail:warnings>0?QualityGateStatus.Warning:QualityGateStatus.Pass;return new(status.ToString(),critical,warnings,Math.Max(0,100-critical*25-warnings*7),reasons);}}